/// <summary>
/// Gets the number sequence for the Nat30 Number for Nat3040.
/// </summary>
/// <returns>
/// Number sequence got.
/// </returns>
public static NumberSequenceReference numRefNat30Number()
{
    NumberSeqScope scope = NumberSeqScopeFactory::createDataAreaScope(curext());
    return NumberSeqReference::findReference(extendedTypeNum(METNat30Number), scope);
}
